import { expect, test } from '../../fixtures/billing';
import { PERIOD_END, projects } from '../../fixtures/testData';

test('BR-04 each line is converted and rounded to the customer\'s currency before its tax is worked out @critical', async ({ proposal }) => {
  await proposal.create(projects.polarReporting, PERIOD_END);

  await expect(proposal.page.locator('#proposal-currency')).toHaveText('USD');
  await expect(proposal.page.locator('#proposal-rate')).toHaveText('1.0835');
  await expect(proposal.lines).toHaveCount(3);

  await expect(proposal.amountOf(1)).toHaveText('1,300.20');
  await expect(proposal.line(1).locator('.line-tax')).toHaveText('331.55');
  await expect(proposal.amountOf(2)).toHaveText('1,040.16');
  await expect(proposal.line(2).locator('.line-tax')).toHaveText('265.24');

  // 252.00 EUR at 1.0835 is 273.042 USD; the line is rounded first and VAT is worked out on 273.04.
  await expect(proposal.amountOf(3)).toHaveText('273.04');
  await expect(proposal.line(3).locator('.line-tax')).toHaveText('69.63');

  // The total is the sum of the rounded lines and their tax.
  await expect(proposal.subtotal).toHaveText('2,613.40');
  await expect(proposal.tax).toHaveText('666.42');
  await expect(proposal.total).toHaveText('3,279.82 USD');

  proposal.page.once('dialog', (dialog) => dialog.accept());
  await proposal.page.locator('#delete-proposal').click();
});
